---@return CharacterBlend
function CharacterBlends:Get(layer, name)
    local blends = self[layer]
    if not blends or type(blends) ~= "table" then
        error(string.format("Layer %s does not have blends", OVERLAY_LAYER:ToString(layer)), 2)
    end

    local blend = {}
    if name ~= "BLEND_NONE" then
        blend = blends[name]
        if not blend or type(blend) ~= "table" then
            error(string.format("Could not find blend %s in layer %s", name, OVERLAY_LAYER:ToString(layer)), 2)
        end
    end

    blend.id = name
    blend.layer = layer

    return CharacterBlend:New(blend)
end
